UPDATE [Выбросы ПГ] AS PG SET PG.GAZ_ekol = IIf(PG.GAZ_ekol Is Null,0,PG.GAZ_ekol), PG.CO2_gaz = IIf(PG.CO2_gaz Is Null,0,PG.CO2_gaz), PG.MAZUT_ekol = IIf(PG.[MAZUT_ekol] Is Null,0,PG.[MAZUT_ekol]), PG.CO2_mazut = IIf(PG.CO2_mazut Is Null,0,PG.CO2_mazut), PG.UGOL_ekol = IIf(PG.UGOL_ekol Is Null,0,PG.UGOL_ekol), PG.CO2_ugol = IIf(PG.CO2_ugol Is Null,0,PG.CO2_ugol), PG.CO2 = IIf(PG.CO2 Is Null,0,PG.CO2), PG.SF6 = IIf(PG.SF6 Is Null,0,PG.SF6)
WHERE ((PG.GAZ_ekol Is Null) Or (PG.CO2_gaz Is Null) Or (PG.MAZUT_ekol Is Null) Or (PG.CO2_mazut Is Null) Or (PG.UGOL_ekol Is Null) Or (PG.CO2_ugol Is Null) Or (PG.CO2 Is Null) Or (PG.SF6 Is Null));
